import {
  LOCALE_COOKIE,
  LOCALE_HEADER,
  routingStrategy,
} from "@{{projectName}}/i18n/config";
import {
  localeFromPathname,
  negotiateRequestLocale,
  stripLocalePrefix,
} from "@{{projectName}}/i18n/routing";

